@namespace sv_5f66bee0dcef4dc18ef0ff988f1e5329.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < Steps.Length; i++)
        {
            var step = i;
            var status = step < CurrentStep ? "completed" : step == CurrentStep ? "current" : "future";
            <li class="step-item @status"
                @onclick="() => OnStepClick(step)"
                role="button"
                aria-current="@(step == CurrentStep ? "step" : null)">
                <span class="step-number">
                    @if (step < CurrentStep)
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        @(step + 1)
                    }
                </span>
                <span class="step-label">@Steps[step]</span>
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private static readonly string[] Steps = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private async Task OnStepClick(int step)
    {
        if (step < CurrentStep)
        {
            await OnStepSelected.InvokeAsync(step);
        }
    }
}

