arguments.file_text:
@page "/apply"
@using sv_5f66bee0dcef4dc18ef0ff988f1e5329.Components.Pages.Apply
@using sv_5f66bee0dcef4dc18ef0ff988f1e5329.Models
@using sv_5f66bee0dcef4dc18ef0ff988f1e5329.Services
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="application-wizard">
    <StepIndicator CurrentStep="_currentStep" OnStepSelected="GoToStep" />

    <div class="step-content">
        @switch (_currentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync"
                                  OnNext="HandlePersonalNext" />
                break;
            case 1:
                <WorkHistoryStep Entries="_workEntries" OnNext="HandleWorkNext" OnBack="GoBack" />
                break;
            case 2:
                <ReferencesStep References="_references" OnNext="HandleReferencesNext" OnBack="GoBack" />
                break;
            case 3:
                <CoverLetterStep CoverLetter="@_coverLetter" OnNext="HandleCoverLetterNext" OnBack="GoBack" />
                break;
            case 4:
                <ReviewStep FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                            WorkEntries="_workEntries" References="_references" CoverLetter="@_coverLetter"
                            IsSubmitted="_isSubmitted" ApplicationId="_applicationId"
                            OnSubmit="HandleSubmit" OnBack="GoBack" OnEdit="GoToStep" />
                break;
        }
    </div>
</div>

@code {
    private int _currentStep;
    private bool _isSubmitted;
    private int? _applicationId;

    // Step 1 state
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2 state
    private List<WorkEntryForm.WorkEntryModel> _workEntries = new() { new() };

    // Step 3 state
    private List<ReferenceForm.ReferenceModel> _references = new() { new(), new() };

    // Step 4 state
    private string _coverLetter = "";

    private void HandlePersonalNext((string FullName, string Email, string Phone, string Address) data)
    {
        _fullName = data.FullName;
        _email = data.Email;
        _phone = data.Phone;
        _address = data.Address;
        _currentStep = 1;
    }

    private void HandleWorkNext(List<WorkEntryForm.WorkEntryModel> entries)
    {
        _workEntries = entries;
        _currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferenceForm.ReferenceModel> refs)
    {
        _references = refs;
        _currentStep = 3;
    }

    private void HandleCoverLetterNext(string coverLetter)
    {
        _coverLetter = coverLetter;
        _currentStep = 4;
    }

    private async Task HandleSubmit()
    {
        var application = new JobApplication(
            new PersonalInfo(_fullName, _email, _phone, _address),
            new WorkHistory(_workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()),
            _references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            _coverLetter
        );

        _applicationId = await ApplicationService.SubmitApplicationAsync(application);
        _isSubmitted = true;
    }

    private void GoToStep(int step)
    {
        _currentStep = step;
    }

    private void GoBack()
    {
        if (_currentStep > 0) _currentStep--;
    }
}

.application-wizard {
    max-width: 800px;
    margin: 2rem auto;
    padding: 0 1rem;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    justify-content: space-between;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    position: relative;
    cursor: default;
}

.step-item.completed {
    cursor: pointer;
}

.step-item.completed .step-number {
    background-color: #28a745;
    color: white;
}

.step-item.current .step-number {
    background-color: #0d6efd;
    color: white;
}

.step-item.future .step-number {
    background-color: #e9ecef;
    color: #6c757d;
}

.step-item.future .step-label {
    color: #adb5bd;
}

.step-number {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.9rem;
    margin-bottom: 0.5rem;
}

.checkmark {
    font-size: 1.1rem;
}

.step-label {
    font-size: 0.8rem;
    text-align: center;
    color: #495057;
}

/* Form Styles */
.step-form {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    padding: 2rem;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.25rem;
    color: #212529;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 1rem;
    box-sizing: border-box;
}

.form-control:focus {
    border-color: #86b7fe;
    outline: 0;
    box-shadow: 0 0 0 0.2rem rgba(13, 110, 253, 0.25);
}

.form-row {
    display: flex;
    gap: 1rem;
}

.form-row .form-group {
    flex: 1;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    font-weight: normal !important;
    margin-top: 0.25rem;
}

/* Buttons */
.step-actions {
    display: flex;
    justify-content: flex-end;
    gap: 0.75rem;
    margin-top: 1.5rem;
    padding-top: 1.5rem;
    border-top: 1px solid #e9ecef;
}

.btn {
    padding: 0.5rem 1.25rem;
    border-radius: 4px;
    font-size: 1rem;
    font-weight: 500;
    cursor: pointer;
    border: none;
    transition: background-color 0.15s;
}

.btn:disabled {
    opacity: 0.65;
    cursor: not-allowed;
}

.btn-primary {
    background-color: #0d6efd;
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background-color: #0b5ed7;
}

.btn-outline {
    background-color: transparent;
    color: #0d6efd;
    border: 1px solid #0d6efd;
}

.btn-outline:hover {
    background-color: #0d6efd;
    color: white;
}

.btn-secondary {
    background-color: #6c757d;
    color: white;
}

.btn-secondary:hover {
    background-color: #5c636a;
}

.btn-danger {
    background-color: #dc3545;
    color: white;
}

.btn-sm {
    padding: 0.25rem 0.75rem;
    font-size: 0.85rem;
}

.btn-link {
    background: none;
    border: none;
    color: #0d6efd;
    cursor: pointer;
    font-size: 0.9rem;
    text-decoration: underline;
    padding: 0;
}

.btn-link:hover {
    color: #0a58ca;
}

/* Validation */
.validation-summary {
    background-color: #f8d7da;
    border: 1px solid #f5c2c7;
    color: #842029;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-top: 1rem;
