toolArgs.file_text:
.application-wizard {
    max-width: 800px;
    margin: 2rem auto;
    padding: 0 1rem;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    justify-content: space-between;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    position: relative;
    cursor: default;
}

.step-item.completed {
    cursor: pointer;
}

.step-item.completed .step-number {
    background-color: #28a745;
    color: white;
}

.step-item.current .step-number {
    background-color: #0d6efd;
    color: white;
}

.step-item.future .step-number {
    background-color: #e9ecef;
    color: #6c757d;
}

.step-item.future .step-label {
    color: #adb5bd;
}

.step-number {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.9rem;
    margin-bottom: 0.5rem;
}

.checkmark {
    font-size: 1.1rem;
}

.step-label {
    font-size: 0.8rem;
    text-align: center;
    color: #495057;
}

/* Form Styles */
.step-form {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    padding: 2rem;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.25rem;
    color: #212529;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 1rem;
    box-sizing: border-box;
}

.form-control:focus {
    border-color: #86b7fe;
    outline: 0;
    box-shadow: 0 0 0 0.2rem rgba(13, 110, 253, 0.25);
}

.form-row {
    display: flex;
    gap: 1rem;
}

.form-row .form-group {
    flex: 1;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    font-weight: normal !important;
    margin-top: 0.25rem;
}

/* Buttons */
.step-actions {
    display: flex;
    justify-content: flex-end;
    gap: 0.75rem;
    margin-top: 1.5rem;
    padding-top: 1.5rem;
    border-top: 1px solid #e9ecef;
}

.btn {
    padding: 0.5rem 1.25rem;
    border-radius: 4px;
    font-size: 1rem;
    font-weight: 500;
    cursor: pointer;
    border: none;
    transition: background-color 0.15s;
}

.btn:disabled {
    opacity: 0.65;
    cursor: not-allowed;
}

.btn-primary {
    background-color: #0d6efd;
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background-color: #0b5ed7;
}

.btn-outline {
    background-color: transparent;
    color: #0d6efd;
    border: 1px solid #0d6efd;
}

.btn-outline:hover {
    background-color: #0d6efd;
    color: white;
}

.btn-secondary {
    background-color: #6c757d;
    color: white;
}

.btn-secondary:hover {
    background-color: #5c636a;
}

.btn-danger {
    background-color: #dc3545;
    color: white;
}

.btn-sm {
    padding: 0.25rem 0.75rem;
    font-size: 0.85rem;
}

.btn-link {
    background: none;
    border: none;
    color: #0d6efd;
    cursor: pointer;
    font-size: 0.9rem;
    text-decoration: underline;
    padding: 0;
}

.btn-link:hover {
    color: #0a58ca;
}

/* Validation */
.validation-summary {
    background-color: #f8d7da;
    border: 1px solid #f5c2c7;
    color: #842029;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-top: 1rem;
}

.field-error {
    color: #dc3545;
    font-size: 0.85rem;
    margin-top: 0.25rem;
    display: block;
}

/* Work Entry */
.work-entry-form {
    border: 1px solid #e9ecef;
    border-radius: 6px;
    padding: 1.5rem;
    margin-bottom: 1rem;
    background: #f8f9fa;
}

.entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.entry-header h4 {
    margin: 0;
}

/* Reference Form */
.reference-form {
    border: 1px solid #e9ecef;
    border-radius: 6px;
    padding: 1.5rem;
    margin-bottom: 1rem;
    background: #f8f9fa;
    position: relative;
}

.reference-form h4 {
    margin-top: 0;
}

.reference-form > .btn-danger {
    position: absolute;
    top: 1rem;
    right: 1rem;
}

/* Cover Letter */
.cover-letter-textarea {
    min-height: 250px;
    resize: vertical;
}

.char-count {
    display: block;
    text-align: right;
    font-size: 0.85rem;
    color: #6c757d;
    margin-top: 0.25rem;
}

.char-count-warning {
    color: #dc3545;
}

/* Review Step */
.review-section {
    border-bottom: 1px solid #e9ecef;
    padding-bottom: 1.25rem;
    margin-bottom: 1.25rem;
}

.review-section:last-of-type {
    border-bottom: none;
}

.review-section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.review-section-header h3 {
    margin: 0 0 0.75rem 0;
    font-size: 1.1rem;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #6c757d;
}

.review-work-entry {
    margin-bottom: 0.75rem;
    padding-left: 0.5rem;
    border-left: 3px solid #0d6efd;
}

.review-reference {
    margin-bottom: 0.5rem;
}

.text-muted {
    color: #6c757d;
    font-size: 0.9rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 4px;
    border: 1px solid #e9ecef;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 3rem 2rem;
}

.confirmation h3 {
    color: #28a745;
    font-size: 1.5rem;
    margin-bottom: 1rem;
}

.confirmation p {
    font-size: 1.1rem;
    color: #495057;
}

.btn-submit {
    font-size: 1.1rem;
    padding: 0.75rem 2rem;
}

