@namespace sv_5f66bee0dcef4dc18ef0ff988f1e5329.Components.Pages.Apply

<div class="work-entry-form">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn btn-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company" @onchange="OnCompanyChanged" class="form-control" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title" @onchange="OnTitleChanged" class="form-control" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="OnStartDateChanged" class="form-control" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")" @onchange="OnEndDateChanged" class="form-control" disabled="@_isCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@_isCurrent" @onchange="HandleCurrentToggle" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Entry.Description" @onchange="OnDescriptionChanged" class="form-control" rows="3"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool _isCurrent;

    protected override void OnParametersSet()
    {
        _isCurrent = Entry.EndDate is null && Entry.StartDate != default;
    }

    private void OnCompanyChanged(ChangeEventArgs e)
    {
        Update(Entry with { Company = (string?)e.Value ?? "" });
    }

    private void OnTitleChanged(ChangeEventArgs e)
    {
        Update(Entry with { Title = (string?)e.Value ?? "" });
    }

    private void OnStartDateChanged(ChangeEventArgs e)
    {
        var val = (string?)e.Value;
        if (DateTime.TryParse(val, out var date))
        {
            Update(Entry with { StartDate = date });
        }
    }

    private void OnEndDateChanged(ChangeEventArgs e)
    {
        var val = (string?)e.Value;
        if (string.IsNullOrEmpty(val))
            Update(Entry with { EndDate = null });
        else if (DateTime.TryParse(val, out var date))
            Update(Entry with { EndDate = date });
    }

    private void OnDescriptionChanged(ChangeEventArgs e)
    {
        Update(Entry with { Description = (string?)e.Value ?? "" });
    }

    private void Update(WorkEntryModel updated)
    {
        OnChanged.InvokeAsync(updated);
    }

    private void HandleCurrentToggle(ChangeEventArgs e)
    {
        _isCurrent = (bool)(e.Value ?? false);
        if (_isCurrent)
        {
            Update(Entry with { EndDate = null });
        }
    }

    public record WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public string Description { get; set; } = "";
    }
}

